package com.dreamspex.admin;

import com.dreamspex.catalog.entity.Category;
import com.dreamspex.catalog.entity.Product;
import com.dreamspex.catalog.entity.ProductImage;
import com.dreamspex.catalog.repository.CategoryRepository;
import com.dreamspex.catalog.repository.ProductRepository;
import com.dreamspex.audit.AuditLogService;import com.dreamspex.common.ApiException;
import com.dreamspex.prescription.PrescriptionStorage;
import com.dreamspex.security.CurrentUser;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import org.springframework.web.multipart.MultipartFile;
import java.io.IOException;
import java.io.InputStream;
import java.time.Instant;
import java.util.*;
import static com.dreamspex.admin.HomepageCmsDtos.*;

@Service
public class HomepageCmsService {
 private final BannerRepository banners; private final HomepageSectionRepository sections; private final HomepageCardRepository cards; private final ProductRepository products; private final CategoryRepository categories; private final CurrentUser current; private final AuditLogService audit; private final Optional<HomepageImageStorage> storage;
 public HomepageCmsService(BannerRepository b,HomepageSectionRepository s,HomepageCardRepository cards,ProductRepository p,CategoryRepository c,CurrentUser u,AuditLogService a,Optional<HomepageImageStorage> storage){banners=b;sections=s;this.cards=cards;products=p;categories=c;current=u;audit=a;this.storage=storage;}
 @Transactional(readOnly=true) public HomepageResponse publicHome(){Instant now=Instant.now();var publishedProducts=products.findByStatusAndDeletedAtIsNullOrderByCreatedAtDesc("PUBLISHED");return new HomepageResponse(banners.findByStatusOrderBySortOrderAsc("PUBLISHED").stream().filter(b->(b.getStartsAt()==null||!b.getStartsAt().isAfter(now))&&(b.getEndsAt()==null||b.getEndsAt().isAfter(now))).map(this::banner).toList(),sections.findByEnabledTrueAndStatusOrderByDisplayOrderAsc("PUBLISHED").stream().map(this::section).toList(),cards.findByEnabledTrueAndStatusOrderBySectionKeyAscDisplayOrderAscIdAsc("PUBLISHED").stream().filter(c->isPublicCard(c,publishedProducts)).map(this::card).toList());}
 @Transactional(readOnly=true) public HomepageResponse adminHome(){return new HomepageResponse(banners.findAllByOrderBySortOrderAsc().stream().map(this::banner).toList(),sections.findAllByOrderByDisplayOrderAsc().stream().map(this::section).toList(),cards.findAllByOrderBySectionKeyAscDisplayOrderAscIdAsc().stream().map(this::card).toList());}
 @Transactional public BannerResponse saveBanner(Authentication a,String id,BannerRequest r){var actor=current.require(a);if(r.startsAt()!=null&&r.endsAt()!=null&&!r.endsAt().isAfter(r.startsAt()))throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_SCHEDULE","Banner end time must be after its start time.");String requestedMediaType=blank(r.desktopMediaType());String mediaType=requestedMediaType==null?"IMAGE":normalized(requestedMediaType);if(!Set.of("IMAGE","VIDEO").contains(mediaType))throw invalidBanner("Select IMAGE or VIDEO desktop media.");String desktopImage=blank(r.desktopImageUrl());String mobileImage=blank(r.mobileImageUrl());String desktopVideo=blank(r.desktopVideoUrl());String videoStorageKey=blank(r.desktopVideoStorageKey());if("IMAGE".equals(mediaType)&&desktopImage==null)throw invalidBanner("A desktop image is required for image banners.");if("VIDEO".equals(mediaType)){if(desktopVideo==null||!isStoredVideo(desktopVideo,videoStorageKey))throw invalidBanner("Upload a valid MP4 or WebM desktop video.");if(mobileImage==null)throw invalidBanner("A mobile image is required for video banners.");}if(desktopImage!=null)validateUrl(desktopImage);if(mobileImage!=null)validateUrl(mobileImage);if(r.linkUrl()!=null&&!r.linkUrl().isBlank())validateUrl(r.linkUrl());if(r.secondaryLinkUrl()!=null&&!r.secondaryLinkUrl().isBlank())validateUrl(r.secondaryLinkUrl());Banner b=id==null?new Banner():banners.findById(id).orElseThrow(()->notFound("BANNER_NOT_FOUND"));b.setTitle(r.title().trim());b.setSubtitle(blank(r.subtitle()));b.setDescription(blank(r.description()));b.setImageUrl(desktopImage==null?mobileImage:desktopImage);b.setMobileImageUrl(mobileImage);b.setDesktopStorageKey(blank(r.desktopStorageKey()));b.setMobileStorageKey(blank(r.mobileStorageKey()));b.setDesktopMediaType(mediaType);b.setDesktopVideoUrl(desktopVideo);b.setDesktopVideoStorageKey(videoStorageKey);b.setButtonText(blank(r.buttonText()));b.setLinkUrl(blank(r.linkUrl()));b.setSecondaryButtonText(blank(r.secondaryButtonText()));b.setSecondaryLinkUrl(blank(r.secondaryLinkUrl()));b.setPositioning(blank(r.positioning()));b.setSortOrder(r.sortOrder());b.setStatus(validStatus(r.status()));b.setStartsAt(r.startsAt());b.setEndsAt(r.endsAt());Banner saved=banners.save(b);audit.record(actor,"CMS_BANNER_SAVED","BANNER",saved.getId());return banner(saved);}
 @Transactional public SectionResponse saveSection(org.springframework.security.core.Authentication a,String id,SectionRequest r){var actor=current.require(a);String type=r.sectionType().trim().toUpperCase();if(!Set.of("CATEGORY_GRID","PRODUCT_GRID","TRENDING_PRODUCTS","BEST_SELLERS","NEW_ARRIVALS","FEATURED_COLLECTION","PROMO_BANNER","RICH_TEXT","CATEGORY_BANNER_CARDS","FRAME_SHAPE_CARDS","PROMOTIONAL_CARDS","SHOP_BY_WEARER","EXPLORE_BY_BRAND").contains(type))throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_SECTION_TYPE","Unsupported homepage section type.");if(r.contentJson()!=null&&!r.contentJson().isBlank())try{new com.fasterxml.jackson.databind.ObjectMapper().readTree(r.contentJson());}catch(Exception e){throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_CONTENT_JSON","Section content must be valid JSON.");}var actorUser=actor;HomepageSection s=id==null?new HomepageSection():sections.findById(id).orElseThrow(()->notFound("SECTION_NOT_FOUND"));s.setSlug(r.slug().trim().toLowerCase());s.setSectionType(type);s.setTitle(blank(r.title()));s.setSubtitle(blank(r.subtitle()));s.setContentJson(blank(r.contentJson()));s.setDisplayOrder(r.displayOrder());s.setStatus(validStatus(r.status()));s.setEnabled(r.enabled());s.getProducts().clear();if(r.productIds()!=null)r.productIds().forEach(x->s.getProducts().add(products.findByIdAndStatusAndDeletedAtIsNull(x,"PUBLISHED").orElseThrow(()->notFound("PRODUCT_NOT_FOUND"))));s.getCategories().clear();if(r.categoryIds()!=null)r.categoryIds().forEach(x->s.getCategories().add(categories.findById(x).filter(c->c.getDeletedAt()==null&&"ACTIVE".equals(c.getStatus())).orElseThrow(()->notFound("CATEGORY_NOT_FOUND"))));s.setUpdatedBy(actorUser);s.setUpdatedAt(Instant.now());HomepageSection saved=sections.save(s);audit.record(actorUser,"CMS_SECTION_SAVED","HOMEPAGE_SECTION",saved.getId());return section(saved);}
 @Transactional public HomepageCardResponse saveCard(Authentication authentication,String id,HomepageCardRequest request){var actor=current.require(authentication);String sectionKey=normalized(request.sectionKey());String destinationType=normalized(request.destinationType());String status=validStatus(request.status());if(!Set.of("CATEGORY_BANNER","FRAME_SHAPE","TRENDING_PRODUCT","PROMOTIONAL","SHOP_BY_WEARER","EXPLORE_BY_BRAND").contains(sectionKey))throw invalidCard("Unsupported homepage card section.");if(request.displayOrder()<0)throw invalidCard("Display order cannot be negative.");if(request.imageUrl()!=null&&!request.imageUrl().isBlank())validateUrl(request.imageUrl());Destination destination=resolveDestination(sectionKey,destinationType,request.destinationValue());HomepageCard card=id==null?new HomepageCard():cards.findById(id).orElseThrow(()->notFound("HOMEPAGE_CARD_NOT_FOUND"));card.setSectionKey(sectionKey);card.setTitle(request.title().trim());card.setSubtitle(blank(request.subtitle()));card.setDescription(blank(request.description()));card.setImageUrl(blank(request.imageUrl()));card.setImageStorageKey(blank(request.imageStorageKey()));card.setButtonText(blank(request.buttonText()));card.setDestinationType(destination.type());card.setDestinationValue(destination.value());card.setDisplayOrder(request.displayOrder());card.setStatus(status);card.setEnabled(request.enabled());card.setProduct(destination.product());card.setCategory(destination.category());card.setUpdatedBy(actor);card.setUpdatedAt(Instant.now());HomepageCard saved=cards.save(card);audit.record(actor,id==null?"CMS_CARD_CREATED":"CMS_CARD_UPDATED","HOMEPAGE_CARD",saved.getId());return card(saved);}
 @Transactional public void deleteCard(Authentication authentication,String id){var actor=current.require(authentication);if(!cards.existsById(id))throw notFound("HOMEPAGE_CARD_NOT_FOUND");cards.deleteById(id);audit.record(actor,"CMS_CARD_DELETED","HOMEPAGE_CARD",id);}
 @Transactional(readOnly=true) public HomepageCardsPage pageCards(String sectionKey,int page,int pageSize){if(page<0||pageSize<1||pageSize>100)throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_PAGINATION","Page must be zero or greater and page size must be between 1 and 100.");var pageable=org.springframework.data.domain.PageRequest.of(page,pageSize);var result=sectionKey==null||sectionKey.isBlank()?cards.findAllByOrderBySectionKeyAscDisplayOrderAscIdAsc(pageable):cards.findBySectionKeyOrderByDisplayOrderAscIdAsc(normalized(sectionKey),pageable);return new HomepageCardsPage(result.getContent().stream().map(this::card).toList(),page,pageSize,result.getTotalElements());}
 @Transactional public void deleteBanner(Authentication a,String id){var actor=current.require(a);Banner banner=banners.findByIdForUpdate(id).orElseThrow(()->notFound("BANNER_NOT_FOUND"));banners.delete(banner);audit.record(actor,"CMS_BANNER_DELETED","BANNER",id);}
 @Transactional public void deleteSection(Authentication a,String id){var actor=current.require(a);if(!sections.existsById(id))throw notFound("SECTION_NOT_FOUND");sections.deleteById(id);audit.record(actor,"CMS_SECTION_DELETED","HOMEPAGE_SECTION",id);}
 @Transactional public BannerResponse updateBannerStatus(Authentication a,String id,String status){var actor=current.require(a);Banner banner=banners.findById(id).orElseThrow(()->notFound("BANNER_NOT_FOUND"));banner.setStatus(validStatus(status));Banner saved=banners.save(banner);audit.record(actor,"CMS_BANNER_STATUS_CHANGED","BANNER",id);return banner(saved);}
 @Transactional public UploadResponse upload(Authentication a,MultipartFile file){
  if(file==null||file.isEmpty()||file.getOriginalFilename()==null||file.getOriginalFilename().isBlank())
   throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_IMAGE","A non-empty image file with a filename is required.");
  if(file.getSize()>10_000_000)
   throw new ApiException(HttpStatus.PAYLOAD_TOO_LARGE,"IMAGE_TOO_LARGE","Images must be 10 MB or smaller.");
  if(!List.of("image/jpeg","image/png","image/webp").contains(file.getContentType()))
   throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_IMAGE_TYPE","Use a JPEG, PNG, or WebP image.");
  try{
   PrescriptionStorage.StoredFile f=storage.orElseThrow(()->new ApiException(HttpStatus.SERVICE_UNAVAILABLE,"STORAGE_UNAVAILABLE","Image storage is not configured.")).store(file);
   audit.record(current.require(a),"CMS_IMAGE_UPLOADED","CMS_IMAGE",f.storageKey());
   return new UploadResponse("/api/v1/cms/images/"+f.storageKey(),f.storageKey());
  }catch(IOException|SecurityException e){
   throw new ApiException(HttpStatus.BAD_GATEWAY,"IMAGE_UPLOAD_FAILED","Image could not be stored. Check the configured storage directory and its write permissions.",e);
  }
 }
  @Transactional public UploadResponse uploadVideo(Authentication a,MultipartFile file){
   if(file==null||file.isEmpty()||file.getOriginalFilename()==null||file.getOriginalFilename().isBlank())
    throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_VIDEO","A non-empty video file with a filename is required.");
   if(file.getSize()>100_000_000)
    throw new ApiException(HttpStatus.PAYLOAD_TOO_LARGE,"VIDEO_TOO_LARGE","Videos must be 100 MB or smaller.");
   String contentType=file.getContentType();
   String originalName=file.getOriginalFilename().toLowerCase(Locale.ROOT);
   boolean supportedVideoType="video/mp4".equals(contentType)||"video/webm".equals(contentType);
   boolean filenameMatchesType=("video/mp4".equals(contentType)&&originalName.endsWith(".mp4"))
     ||("video/webm".equals(contentType)&&originalName.endsWith(".webm"));
   if(!supportedVideoType||!filenameMatchesType)
    throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_VIDEO_TYPE","Use an MP4 or WebM video.");
   try(InputStream input=file.getInputStream()){
    byte[] signature=input.readNBytes(12);
    boolean validSignature="video/mp4".equals(contentType)
      ?signature.length>=8&&signature[4]=='f'&&signature[5]=='t'&&signature[6]=='y'&&signature[7]=='p'
      :signature.length>=4&&(signature[0]&0xff)==0x1a&&(signature[1]&0xff)==0x45&&(signature[2]&0xff)==0xdf&&(signature[3]&0xff)==0xa3;
    if(!validSignature)throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_VIDEO","The video contents do not match the selected MP4 or WebM type.");
   }catch(IOException e){throw new ApiException(HttpStatus.BAD_GATEWAY,"VIDEO_UPLOAD_FAILED","Video could not be read.",e);}
   try{
    PrescriptionStorage.StoredFile stored=storage.orElseThrow(()->new ApiException(HttpStatus.SERVICE_UNAVAILABLE,"STORAGE_UNAVAILABLE","Video storage is not configured.")).storeVideo(file);
    audit.record(current.require(a),"CMS_VIDEO_UPLOADED","CMS_VIDEO",stored.storageKey());
    return new UploadResponse("/api/v1/cms/videos/"+stored.storageKey(),stored.storageKey());
   }catch(IOException|SecurityException e){
    throw new ApiException(HttpStatus.BAD_GATEWAY,"VIDEO_UPLOAD_FAILED","Video could not be stored. Check the configured storage directory and its write permissions.",e);
   }
  }
 private Destination resolveDestination(String sectionKey,String type,String rawValue){String value=rawValue==null?"":rawValue.trim();if(value.isBlank())throw invalidCard("A destination is required.");String requiredType=switch(sectionKey){case "CATEGORY_BANNER"->"CATEGORY";case "FRAME_SHAPE"->"SHAPE";case "TRENDING_PRODUCT"->"PRODUCT";case "SHOP_BY_WEARER"->"GENDER";case "EXPLORE_BY_BRAND"->"BRAND";default->null;};if(requiredType!=null&&!requiredType.equals(type))throw invalidCard("This card section requires a "+requiredType+" destination.");return switch(type){case "PAGE"->{try{var uri=java.net.URI.create(value);if(!value.startsWith("/")||value.startsWith("//")||value.indexOf('\\')>=0||uri.getScheme()!=null||uri.getRawAuthority()!=null)throw new IllegalArgumentException();}catch(IllegalArgumentException e){throw invalidCard("Page destinations must be safe internal paths.");}yield new Destination(type,value,null,null);}case "CATEGORY"->{Category category=categories.findBySlugAndCategoryTypeAndStatusAndDeletedAtIsNull(value,"CATALOG","ACTIVE").orElseThrow(()->invalidCard("Select an active catalogue category."));yield new Destination(type,category.getSlug(),null,category);}case "PRODUCT"->{Product product=products.findByIdAndStatusAndDeletedAtIsNull(value,"PUBLISHED").orElseThrow(()->invalidCard("Select a published catalogue product."));yield new Destination(type,product.getId(),product,null);}case "BRAND","GENDER","SHAPE"->{Product match=products.findByStatusAndDeletedAtIsNullOrderByCreatedAtDesc("PUBLISHED").stream().filter(product->type.equals("BRAND")?product.getBrand()!=null&&product.getBrand().equalsIgnoreCase(value):type.equals("GENDER")?value.equalsIgnoreCase(product.getGender()):value.equalsIgnoreCase(product.getFrameShape())).findFirst().orElseThrow(()->invalidCard("Select a value represented in the published product catalogue."));String canonical=type.equals("BRAND")?match.getBrand():type.equals("GENDER")?match.getGender():match.getFrameShape();yield new Destination(type,canonical,null,null);}default->throw invalidCard("Unsupported card destination type.");};}
 private record Destination(String type,String value,Product product,Category category){}
 private boolean isPublicCard(HomepageCard card,List<Product> publishedProducts){return switch(card.getDestinationType()){case "PRODUCT"->card.getProduct()!=null&&card.getProduct().getDeletedAt()==null&&"PUBLISHED".equals(card.getProduct().getStatus());case "CATEGORY"->card.getCategory()!=null&&card.getCategory().getDeletedAt()==null&&"ACTIVE".equals(card.getCategory().getStatus());case "BRAND"->publishedProducts.stream().anyMatch(p->p.getBrand()!=null&&p.getBrand().equalsIgnoreCase(card.getDestinationValue()));case "GENDER"->publishedProducts.stream().anyMatch(p->card.getDestinationValue().equalsIgnoreCase(p.getGender()));case "SHAPE"->publishedProducts.stream().anyMatch(p->card.getDestinationValue().equalsIgnoreCase(p.getFrameShape()));case "PAGE"->true;default->false;};}
 private HomepageCardResponse card(HomepageCard value){Product product=value.getProduct();Category category=value.getCategory();String image=blank(value.getImageUrl());if(image==null&&product!=null)image=product.getImages().stream().filter(ProductImage::isPrimaryImage).map(ProductImage::getImageUrl).findFirst().orElse(null);if(image==null&&category!=null)image=category.getImageUrl();return new HomepageCardResponse(value.getId(),value.getSectionKey(),value.getTitle(),value.getSubtitle(),value.getDescription(),image,value.getImageStorageKey(),value.getButtonText(),value.getDestinationType(),value.getDestinationValue(),value.getDisplayOrder(),value.getStatus(),value.isEnabled(),product==null?null:new ProductCard(product.getId(),product.getName(),product.getSlug(),product.getBrand(),product.getBasePrice(),product.getCompareAtPrice(),product.getImages().stream().filter(ProductImage::isPrimaryImage).map(ProductImage::getImageUrl).findFirst().orElse(null),product.getBadge(),product.getDescription(),product.getCategories().stream().filter(c->c.getDeletedAt()==null).map(Category::getName).findFirst().orElse("Eyewear")),category==null?null:new CategoryCard(category.getId(),category.getName(),category.getSlug(),category.getImageUrl()));}
 private String normalized(String value){return value==null?"":value.trim().toUpperCase(Locale.ROOT);}
 private ApiException invalidCard(String message){return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_HOMEPAGE_CARD",message);}
 private String validStatus(String value){if(!Set.of("DRAFT","PUBLISHED","INACTIVE").contains(value))throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_STATUS","Invalid CMS status.");return value;}
 private void validateUrl(String value){try{var uri=java.net.URI.create(value);if(!Set.of("http","https","/").contains(uri.getScheme()==null?"/":uri.getScheme()))throw new IllegalArgumentException();}catch(IllegalArgumentException e){throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_URL","CMS URLs must use http or https.");}}
 private ApiException invalidBanner(String message){return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"INVALID_BANNER",message);}
 private boolean isStoredVideo(String url,String key){if(key==null||!key.matches("[0-9a-fA-F-]{36}\\.(mp4|webm)"))return false;try{var uri=java.net.URI.create(url);return (uri.getScheme()==null||Set.of("http","https").contains(uri.getScheme()))&&("/api/v1/cms/videos/"+key).equals(uri.getPath());}catch(IllegalArgumentException e){return false;}}
 private String blank(String x){return x==null||x.isBlank()?null:x.trim();} private BannerResponse banner(Banner b){return new BannerResponse(b.getId(),b.getTitle(),b.getSubtitle(),b.getDescription(),b.getImageUrl(),b.getMobileImageUrl(),b.getDesktopStorageKey(),b.getMobileStorageKey(),b.getDesktopMediaType(),b.getDesktopVideoUrl(),b.getDesktopVideoStorageKey(),b.getButtonText(),b.getLinkUrl(),b.getSecondaryButtonText(),b.getSecondaryLinkUrl(),b.getPositioning(),b.getSortOrder(),b.getStatus(),b.getStartsAt(),b.getEndsAt());}
 private SectionResponse section(HomepageSection s){return new SectionResponse(s.getId(),s.getSlug(),s.getSectionType(),s.getTitle(),s.getSubtitle(),s.getContentJson(),s.getDisplayOrder(),s.getStatus(),s.isEnabled(),s.getProducts().stream().filter(p->p.getDeletedAt()==null&&"PUBLISHED".equals(p.getStatus())).map(p->new ProductCard(p.getId(),p.getName(),p.getSlug(),p.getBrand(),p.getBasePrice(),p.getCompareAtPrice(),p.getImages().stream().filter(ProductImage::isPrimaryImage).map(ProductImage::getImageUrl).findFirst().orElse(null),p.getBadge(),p.getDescription(),p.getCategories().stream().filter(c->c.getDeletedAt()==null).map(Category::getName).findFirst().orElse("Eyewear"))).toList(),s.getCategories().stream().filter(c->c.getDeletedAt()==null&&"ACTIVE".equals(c.getStatus())).map(c->new CategoryCard(c.getId(),c.getName(),c.getSlug(),c.getImageUrl())).toList());}
 private <T extends RuntimeException>T notFound(String code){throw new ApiException(HttpStatus.NOT_FOUND,code,"CMS resource was not found.");}
}
